import type { HTMLAttributes, Ref } from 'react';
import { cn } from '../../utils/cn';
import { cardVariants, type CardVariantProps } from './card.variants';

const s = cardVariants();

type DivProps = Omit<HTMLAttributes<HTMLDivElement>, 'className'> & { className?: string; ref?: Ref<HTMLDivElement> };

export interface CardProps extends DivProps {
  /** `default` (card + flat shadow), `well` (lower hierarchy, no shadow) or `outline`. */
  variant?: CardVariantProps['variant'];
}

/** Content surface: 1px border, token radius and a flat shadow. Compose with the Card* parts. */
export function Card({ variant, className, ...props }: CardProps) {
  return <div className={cn(cardVariants({ variant }).root(), className)} {...props} />;
}

export interface CardHeaderProps extends DivProps {
  /** Draws a border between the header and the body. */
  divided?: boolean;
}

/** Title + description on the left, CardAction on the right. */
export function CardHeader({ divided, className, ...props }: CardHeaderProps) {
  return <div className={cn(cardVariants({ divided }).header(), className)} {...props} />;
}

export interface CardTitleProps extends Omit<HTMLAttributes<HTMLHeadingElement>, 'className'> {
  className?: string;
  ref?: Ref<HTMLHeadingElement>;
  /** Heading level that fits the page outline. */
  as?: 'h2' | 'h3' | 'h4';
}

export function CardTitle({ as: Heading = 'h3', className, ...props }: CardTitleProps) {
  return <Heading className={cn(s.title(), className)} {...props} />;
}

export interface CardDescriptionProps extends Omit<HTMLAttributes<HTMLParagraphElement>, 'className'> {
  className?: string;
  ref?: Ref<HTMLParagraphElement>;
}

export function CardDescription({ className, ...props }: CardDescriptionProps) {
  return <p className={cn(s.description(), className)} {...props} />;
}

/** Right-hand header slot (button, menu, status). */
export function CardAction({ className, ...props }: DivProps) {
  return <div className={cn(s.action(), className)} {...props} />;
}

export function CardBody({ className, ...props }: DivProps) {
  return <div className={cn(s.body(), className)} {...props} />;
}

/** Action row on a subtle well, right-aligned. */
export function CardFooter({ className, ...props }: DivProps) {
  return <div className={cn(s.footer(), className)} {...props} />;
}

import { tv, type VariantProps } from '../../utils/tv';

export const cardVariants = tv({
  slots: {
    root: 'overflow-hidden rounded-xl border border-border text-card-foreground',
    header: 'grid grid-cols-[1fr_auto] items-start gap-x-4 px-5 py-4',
    title: 'col-start-1 text-[15px] font-semibold tracking-tight text-foreground',
    description: 'col-start-1 mt-0.5 text-[13px] text-muted-foreground',
    action: 'col-start-2 row-span-2 row-start-1 shrink-0 self-start',
    body: 'px-5 py-4 text-[13px] leading-relaxed text-muted-foreground',
    footer: 'flex flex-wrap items-center justify-end gap-2 border-t border-border bg-secondary/40 px-5 py-3',
  },
  variants: {
    variant: {
      default: { root: 'bg-card shadow-sm' },
      well: { root: 'bg-secondary/50' },
      outline: { root: 'bg-transparent' },
    },
    divided: {
      true: { header: 'border-b border-border' },
    },
  },
  defaultVariants: { variant: 'default', divided: false },
});

export type CardVariantProps = VariantProps<typeof cardVariants>;

export {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardAction,
  CardBody,
  CardFooter,
  type CardProps,
  type CardHeaderProps,
  type CardTitleProps,
  type CardDescriptionProps,
} from './Card';
export { cardVariants, type CardVariantProps } from './card.variants';
export { doc as cardDoc } from './Card.doc';

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'Card',
  group: 'Layout',
  status: 'stable',
  description: 'The base content surface: border, token radius, generous padding and a flat shadow. Parts: Card, CardHeader (optionally divided), CardTitle, CardDescription, CardAction (header right slot), CardBody and CardFooter. Variants: default, well and outline.',
  tokens: ['card', 'card-foreground', 'border', 'secondary', 'muted-foreground', 'shadow-sm', 'radius-xl'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
